'use strict';
function prSvg(body,label=''){return `<svg viewBox="0 0 600 360" ${label?`role="img" aria-label="${senEscape(label)}"`:'aria-hidden="true"'}><rect width="600" height="360" rx="28" fill="#f7f2e5"/>${body}</svg>`;}
function prObject(id,x,y,w=100){const image=pictureIcon(id),view=image.match(/viewBox="([^"]+)"/)?.[1]||'0 0 120 120';return `<svg x="${x}" y="${y}" width="${w}" height="${w}" viewBox="${view}">${svgBody(image)}</svg>`;}
function prFriend(x,y,w=100,animal='rabbit'){return `<svg x="${x}" y="${y}" width="${w}" height="${w*1.5}" viewBox="0 -12 116 178">${friendlyAnimal(animal)}</svg>`;}
function prLandscape(place='garden'){return `<path d="M0 247Q148 190 303 252Q456 209 600 243V360H0Z" fill="#dce6ca"/><path d="M0 295Q190 242 380 296Q520 268 600 290V360H0Z" fill="#d0dfbb"/>${place==='house'?prObject('house',374,87,180):place==='bedroom'?prObject('bed',340,152,200):prObject('tree',425,60,160)}<circle cx="84" cy="65" r="30" fill="#e4c777"/><path d="M190 75q25-24 52 0q30-18 48 4" stroke="#dfe5da" stroke-width="17" stroke-linecap="round" fill="none"/>`;}
function prBridgeArt(s){const built=s?.built||[false,false,false];return prSvg(`<path d="M0 164Q100 135 161 175L153 360H0ZM440 175Q525 140 600 165V360H444Z" fill="#d8e4c8"/><path d="M162 105Q300 150 442 103V360H153Z" fill="#b5d4d6"/><path d="M204 153q72 18 177-3M195 304q97 15 196-3" fill="none" stroke="#d8e9e8" stroke-width="7" stroke-linecap="round"/>${built.map((b,i)=>`<rect x="${156+i*96}" y="222" width="92" height="39" rx="7" fill="${b?'#c99b6c':'#d2e4df'}" stroke="${b?'#8e6b48':'#83a5a1'}" stroke-width="3" ${b?'':'stroke-dasharray="6 6"'}/>${b?`<path d="M${169+i*96} 237h64M${177+i*96} 249h45" stroke="#ad7c50" stroke-width="2"/>`:''}`).join('')}${prFriend(s?.crossed?462:39,104,84)}${prObject('carrot',492,237,65)}`);}
function prGardenArt(s){const step=s?.step||0;return prSvg(`${prLandscape()}<rect x="160" y="253" width="282" height="57" rx="27" fill="#ae8563"/><path d="M180 272q110-30 240 0" stroke="#c59d77" stroke-width="4" fill="none"/>${step===0?prObject('shovel',269,174,90):step===1?'<ellipse cx="300" cy="274" rx="13" ry="9" fill="#e4bf72"/>':step===2?prObject('sprout',235,152,130):prObject('flower',220,110,160)}${step===2?'<path d="M269 184q-8 12 0 15q8-3 0-15M324 194q-8 12 0 15q8-3 0-15" fill="#82b3c1"/>':''}${prFriend(45,133,90)}`);}
// The picnic guest sits on a supported chair beside the table.
function prTableFriend(animal='rabbit'){return `<ellipse cx="45" cy="267" rx="43" ry="6" fill="#536f4c" opacity=".1"/><path d="M16 159V205H78M20 206V264M73 206V264" fill="none" stroke="#a7845c" stroke-width="7"/><rect x="13" y="158" width="10" height="47" rx="4" fill="#8caaa0"/><rect x="17" y="202" width="65" height="9" rx="4" fill="#8caaa0"/><g transform="translate(3 107) scale(.7)">${friendlySeatedAnimal(animal)}</g>`;}
function prTableArt(){return prSvg(`${prLandscape()}<ellipse cx="323" cy="211" rx="210" ry="102" fill="#dcb88a" stroke="#a7845c" stroke-width="4"/><path d="M174 270v70M466 269v71" stroke="#a7845c" stroke-width="15" stroke-linecap="round"/>${prTableFriend()}`);}
function prTrainArt(){return prSvg(`<rect y="267" width="600" height="93" fill="#dce6ca"/><path d="M0 306H600M0 322H600" stroke="#a5b293" stroke-width="5"/>${Array.from({length:12},(_,i)=>`<path d="M${i*54} 300v29" stroke="#bd9c75" stroke-width="5"/>`).join('')}<path d="M12 203h81v77H12Z" fill="#6f9a8d"/><path d="M37 164h57v43H37Z" fill="#6f9a8d"/><rect x="48" y="175" width="30" height="24" rx="4" fill="#e7e6c9"/>${[35,80].map(x=>`<circle cx="${x}" cy="283" r="17" fill="#596a62"/>`).join('')}${[127,282,437].map(x=>`<rect x="${x}" y="143" width="143" height="137" rx="13" fill="#e9c98f" stroke="#b88f59" stroke-width="3"/><circle cx="${x+28}" cy="283" r="16" fill="#596a62"/><circle cx="${x+114}" cy="283" r="16" fill="#596a62"/>`).join('')}`);}
function prStudioArt(s){const place=s?.place||'garden',actor=s?.actor||'rabbit',action=s?.action||'jump';return prSvg(`${prLandscape(place)}<svg x="133" y="74" width="295" height="253" viewBox="0 0 240 180">${svgBody(adultPicture({type:'actor',actor,action,object:'cup'})).replace(/<rect width="240" height="180"[^>]*\/>/,'').replace(/<path d="M0 144[^>]*\/>/,'').replace(/<ellipse cx="120" cy="155"[^>]*\/>/,'')}</svg>`);}
function prCloudArt(s){const removed=s?.removed||[];return prSvg(`<rect width="600" height="360" rx="28" fill="#deedef"/><circle cx="457" cy="95" r="47" fill="#eed28b"/><path d="M0 305Q130 242 300 303Q480 252 600 299V360H0Z" fill="#d8e3ce"/>${[0,1,2].filter(i=>!removed.includes(i)).map(i=>`<g data-cloud-id="${i}" transform="translate(${40+i*165} ${75+i%2*90})"><path d="M0 30q-12-30 24-40q27-36 60-6q35-3 43 33q22 25-7 35H17q-29-2-17-22Z" fill="#fffdf4" stroke="#d3e2df" stroke-width="2"/></g>`).join('')}`);}
function prRoadArt(s){const pos=s?.position||0,red=s?.light==='red';return prSvg(`${prLandscape()}<path d="M0 268H600" stroke="#d7c8ac" stroke-width="90"/><path d="M0 268H600" stroke="#faf3df" stroke-width="4" stroke-dasharray="26 20"/><rect x="414" y="60" width="56" height="125" rx="19" fill="#5b7167"/><circle cx="442" cy="94" r="18" fill="${red?'#cb806d':'#81918b'}"/><circle cx="442" cy="151" r="18" fill="${red?'#81918b':'#86ad78'}"/><path d="M442 185v58" stroke="#5b7167" stroke-width="8"/>${prObject('car',40+pos*165,210,125)}${prObject('house',488,119,105)}`);}
function prCover(id){if(id==='garden')return prGardenArt({step:3});if(id==='bridge')return prBridgeArt({built:[true,false,true]});if(id==='picnic')return prSvg(`${svgBody(prTableArt())}${prObject('bowl',245,145,100)}${prObject('cup',375,132,80)}${prObject('spoon',354,204,73)}`);if(id==='train')return prTrainArt();if(id==='studio'||id==='puppet')return prStudioArt({action:id==='puppet'?'hold':'jump'});if(id==='clouds')return prCloudArt({removed:[1]});if(id==='traffic')return prRoadArt({position:1,light:'red'});if(id==='stretch')return calmPose('tree');if(id==='drums')return prSvg(`<path d="M0 286q300-70 600 0v74H0Z" fill="#dce6ca"/>${[170,400].map((x,i)=>`<path d="M${x-65} 147h130l-15 133h-100Z" fill="${i?'#87a397':'#d4a17e'}" stroke="#597766" stroke-width="4"/><ellipse cx="${x}" cy="149" rx="65" ry="25" fill="#f5e0b4" stroke="#597766" stroke-width="4"/><path d="M${x-54} 185l90 57m-80 12l88-67" stroke="#f6eaca" stroke-width="6"/>`).join('')}`);if(id==='beads')return prSvg(`<path d="M60 108Q300 425 540 108" stroke="#9f997e" stroke-width="4" fill="none"/>${[0,1,2,3,4,5].map((n)=>`<circle cx="${92+n*82}" cy="${108+634*((32+n*82)/480)*(1-(32+n*82)/480)}" r="30" fill="${n%2?'#82a18b':'#ddb58c'}"/><circle cx="${92+n*82}" cy="${108+634*((32+n*82)/480)*(1-(32+n*82)/480)}" r="5" fill="#f9f4e7"/>`).join('')}`);return prSvg(`${prLandscape()}<path d="M104 287L220 217L316 247L445 150" fill="none" stroke="#e2c38e" stroke-width="35" stroke-linecap="round"/>${prObject('house',414,66,105)}${prFriend(62,155,70)}`);}
